import React from "react";

const FUNCTIONS = [
  { name: "_engine",             loc: 9,  kind: "private", section: "helpers" },
  { name: "_normalize_model",    loc: 7,  kind: "private", section: "helpers" },
  { name: "_row_tok_s",          loc: 45, kind: "private", section: "helpers" },
  { name: "_alert_buffer_path",  loc: 3,  kind: "private", section: "alerts" },
  { name: "recent_tok_s",        loc: 30, kind: "public",  section: "baseline" },
  { name: "fastest_known",       loc: 52, kind: "public",  section: "catalog" },
  { name: "check_lag",           loc: 38, kind: "public",  section: "lag" },
  { name: "record_perf_alert",   loc: 40, kind: "public",  section: "alerts" },
  { name: "recent_perf_alerts",  loc: 14, kind: "public",  section: "alerts" },
  { name: "clear_perf_alerts",   loc: 13, kind: "public",  section: "alerts" },
  { name: "regression_warning",  loc: 47, kind: "public",  section: "regression" },
];

const SECTION_COLOR = {
  helpers:    "#6366f1",
  baseline:   "#0ea5e9",
  catalog:    "#f59e0b",
  lag:        "#ef4444",
  alerts:     "#10b981",
  regression: "#8b5cf6",
};

const SECTION_LABEL = {
  helpers:    "private helpers",
  baseline:   "rolling baseline",
  catalog:    "fastest-known",
  lag:        "lag detector",
  alerts:     "alert buffer",
  regression: "regression warner",
};

const MAX_LOC = Math.max(...FUNCTIONS.map(f => f.loc));
const BAR_MAX_W = 380;
const ROW_H = 36;
const LABEL_W = 170;
const PAD = 20;
const CHART_H = FUNCTIONS.length * ROW_H + PAD * 2 + 60;

export default function App() {
  const [hovered, setHovered] = React.useState(null);

  return (
    <div style={{
      fontFamily: "monospace",
      background: "#0f172a",
      minHeight: "100vh",
      color: "#e2e8f0",
      padding: "24px",
    }}>
      <h2 style={{ margin: "0 0 4px", fontSize: 18, color: "#f1f5f9" }}>
        perf.py — function complexity (LoC)
      </h2>
      <p style={{ margin: "0 0 20px", fontSize: 12, color: "#64748b" }}>
        org_llm/perf.py · {FUNCTIONS.reduce((s, f) => s + f.loc, 0)} lines across {FUNCTIONS.length} functions
      </p>

      <svg width={LABEL_W + BAR_MAX_W + PAD * 2 + 50} height={CHART_H}>
        {/* Section legend */}
        {Object.entries(SECTION_LABEL).map(([key, label], i) => (
          <g key={key} transform={`translate(${i * 0}, 0)`}>
          </g>
        ))}

        {/* Bars */}
        {FUNCTIONS.map((fn, i) => {
          const y = PAD + 40 + i * ROW_H;
          const barW = (fn.loc / MAX_LOC) * BAR_MAX_W;
          const color = SECTION_COLOR[fn.section];
          const isHov = hovered === fn.name;
          return (
            <g key={fn.name}
               onMouseEnter={() => setHovered(fn.name)}
               onMouseLeave={() => setHovered(null)}
               style={{ cursor: "default" }}>
              {/* Row bg on hover */}
              {isHov && (
                <rect x={0} y={y - 2} width={LABEL_W + BAR_MAX_W + 60}
                      height={ROW_H - 4} rx={4}
                      fill="rgba(255,255,255,0.05)" />
              )}
              {/* Function label */}
              <text x={LABEL_W - 8} y={y + ROW_H / 2 - 4}
                    textAnchor="end" fontSize={11}
                    fill={fn.kind === "private" ? "#94a3b8" : "#e2e8f0"}
                    fontStyle={fn.kind === "private" ? "italic" : "normal"}>
                {fn.name}
              </text>
              {/* Section dot */}
              <circle cx={LABEL_W + 8} cy={y + ROW_H / 2 - 4} r={4} fill={color} />
              {/* Bar */}
              <rect x={LABEL_W + 18} y={y + 4}
                    width={barW} height={ROW_H - 14}
                    rx={3} fill={color}
                    opacity={isHov ? 1 : 0.75} />
              {/* LoC label */}
              <text x={LABEL_W + 18 + barW + 6}
                    y={y + ROW_H / 2 - 4}
                    fontSize={11} fill={color} fontWeight="bold">
                {fn.loc}
              </text>
            </g>
          );
        })}

        {/* Legend row at top */}
        {Object.entries(SECTION_LABEL).map(([key, label], i) => {
          const cols = 3;
          const col = i % cols;
          const row = Math.floor(i / cols);
          const x = col * 190 + PAD;
          const y = row * 18 + 6;
          return (
            <g key={key}>
              <circle cx={x + 6} cy={y + 6} r={5} fill={SECTION_COLOR[key]} />
              <text x={x + 16} y={y + 11} fontSize={10} fill="#94a3b8">{label}</text>
            </g>
          );
        })}
      </svg>
    </div>
  );
}
